contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient) public payable {
        require(address(this).balance >= 0, "insufficient test balance");
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        if (caller == address(this)) {
            // If caller is this contract, it cannot impersonate owner unless owner == address(this).
        }
        // Use a low-level call to control msg.sender for c.withdrawAll
        // Since c.withdrawAll uses msg.sender, we must call it directly from this contract
        // to pass caller as msg.sender. But caller is a parameter; we can only use it as msg.sender
        // if caller == address(this). To test arbitrary callers, we must simulate by calling from an address.
        // However, the test contract is the only one calling. The rule should consider msg.sender.
        // We cannot make c see a different msg.sender without cheatcodes. So we test with msg.sender = address(this).
        // The rule then: since this contract is not owner (unless owner == address(this)), it reverts.
        // But owner is deployed by this contract, so owner = address(this). Wait, constructor sets owner = _owner.
        // The checker deploys c with owner = ? The constructor is called by the checker. We don't know owner.
        // We can read c.owner() and compare.
        address cOwner = c.owner();

        if (msg.sender == cOwner) {
            // owner path: should succeed
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // non-owner path: should revert
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;
        uint256 recipientBalance = recipient.balance; // cannot read before

        if (msg.sender == cOwner) {
            assert(!reverted && afterBalance == 0);
        } else {
            assert(reverted && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

